    #[test]
    fn test_hover_doc_for_skill_model() {
        let hover = hover_doc(FileType::Skill, "model");
        assert!(hover.is_some());
        let markdown = hover.unwrap().markdown;
        assert!(markdown.contains("model"));
        assert!(markdown.contains("CC-SK-001"));
    }

