        let labels: Vec<_> = completion_candidates(FileType::KiroAgent, content, byte)
            .into_iter()
            .filter(|c| c.kind == CompletionKind::Value)
            .map(|c| c.label)
            .collect();
        assert!(labels.contains(&"@builtin".to_string()), "{labels:?}");
        assert!(labels.contains(&"read".to_string()), "{labels:?}");
